package main

import "fmt"

type CountWriter struct {
    Total int
}

func (w *CountWriter) Write(p []byte) (int, error) {
    w.Total += len(p)
    return len(p), nil
}

func main() {
    cw := &CountWriter{}
    fmt.Fprint(cw, "go-go-go")
    fmt.Println(cw.Total)
}
